style.css:
@-moz-document domain("docs.google.com") {
/* Main Background */
    body, .docs-texteventtarget-iframe, .kix-appview-editor {
        background-color: #e0f7ff !important; /* Light Blue */
    }

    /* Toolbar and Menu */
    .docs-titlebar, .kix-navbar, .docs-menubar, .docs-material {
        background-color: #b3e5fc !important;
        color: #003366 !important;
    }

    /* Sidebar and Panels */
    .kix-sidebar, .docs-explore-widget-container, .modal-dialog {
        background-color: #b3e5fc !important;
        color: #003366 !important;
    }

    /* Comments and Popups */
    .docs-comment-box, .kix-comment-card {
        background-color: #b3e5fc !important;
        color: #003366 !important;
    }

    /* Document Background */
    .kix-page {
        background-color: #e0f7ff !important;
    }

    /* Buttons */
    .goog-inline-block, .goog-toolbar-button, .docs-material-button {
        background-color: #81d4fa !important;
        color: #003366 !important;
        border-color: #4fc3f7 !important;
    }

    /* Hover Effects */
    .goog-inline-block:hover, .goog-toolbar-button:hover, .docs-material-button:hover {
        background-color: #4fc3f7 !important;
    }

    /* Borders */
    .docs-titlebar, .docs-menubar, .kix-sidebar {
        border-color: #4fc3f7 !important;
    }

    /* Text Colors */
    * {
        color: #000 !important; /* Black text */
    }

    /* Disable Text Selection and Background Highlighting */
    * {
        user-select: none !important;
        background-color: transparent !important;
        outline: none !important;
    }
}
